def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    drows=[i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=bg]
    dcols=[j for j in range(w) if len({g[i][j] for i in range(h)})==1 and g[0][j]!=bg]
    cr=[i for i in range(h) if i not in drows]
    cc=[j for j in range(w) if j not in dcols]
    def regions(idx):
        regs=[];cur=[]
        for i in idx:
            if cur and i==cur[-1]+1: cur.append(i)
            else:
                if cur: regs.append(cur)
                cur=[i]
        if cur: regs.append(cur)
        return regs
    rregs=regions(cr); cregs=regions(cc)
    def has_cells(rr,ccr):
        return any(g[i][j]!=bg for i in rr for j in ccr)
    br=[next(r) for r in rregs if has_cells(r,cc)][0]
    bc=[next(c) for c in cregs if has_cells(br,c)][0]
    blk=[[g[i][j] for j in bc] for i in br]
    bh,bw=len(blk),len(blk[0])
    dc=drows[0] if drows else None
    dcl=dcols[0] if dcols else None
    pv=bh+1 if dc is not None else bh
    ph=bw+1 if dcl is not None else bw
    out=[]
    for i in range(h):
        row=[]
        for j in range(w):
            ci,cj=i%pv,j%ph
            if dc is not None and ci==bh: row.append(g[dc][0])
            elif dcl is not None and cj==bw: row.append(g[0][dcl])
            else: row.append(blk[ci][cj])
        out.append(row)
    return out
